const BASE_URL = `https://api.telegram.org/bot${BOT_TOKEN}`;

const itemJson = $input.item.json || {};
const rawBody = itemJson.body || itemJson;
const callback = rawBody.callback_query;
const isBusinessMessage = Boolean(rawBody.business_message);
const businessConnection = rawBody.business_connection;
const message = rawBody.business_message || rawBody.message;

let chatId = 0;
let fromId = 0;
let text = '';
let isCallback = false;
let callbackData = '';
let isPhoto = false;
let photoFileId = '';
let photoCaption = '';
let chatType = 'private';
let messageThreadId = undefined;
let businessConnectionId = '';

if (rawBody.business_message?.business_connection_id) {
  businessConnectionId = rawBody.business_message.business_connection_id;
} else if (businessConnection?.id) {
  businessConnectionId = businessConnection.id;
}

const msgUser = callback ? callback.from : (message ? message.from : {});
const senderFirstName = msgUser?.first_name || '';
const senderLastName = msgUser?.last_name || '';
const senderName = ((senderFirstName + ' ' + senderLastName).trim()) || 'Tamu Telegram';
const senderUsername = msgUser?.username ? ('@' + msgUser.username) : '-';

if (callback) {
  isCallback = true;
  chatId = callback.message?.chat?.id || 0;
  fromId = callback.from?.id || 0;
  callbackData = callback.data || '';
  chatType = callback.message?.chat?.type || 'private';
  messageThreadId = callback.message?.message_thread_id;
} else if (message) {
  chatId = message.chat?.id || 0;
  fromId = message.from?.id || 0;
  text = (message.text || '').trim();
  chatType = message.chat?.type || 'private';
  messageThreadId = message.message_thread_id;
  if (message.photo) {
    isPhoto = true;
    const photos = message.photo;
    photoFileId = photos[photos.length - 1].file_id;
    photoCaption = (message.caption || '').trim();
  }
} else if (businessConnection) {
  return {
    chatId: businessConnection.user_chat_id || 0,
    fromId: businessConnection.user?.id || 0,
    businessConnectionId: businessConnection.id,
    handled: true,
    action: 'save_business_connection'
  };
}

async function tgPost(method, body) {
  return await this.helpers.httpRequest({ method: 'POST', url: `${BASE_URL}/${method}`, body, json: true });
}

async function sendMessage(chatId, text, replyMarkup) {
  const body = { chat_id: chatId, text, parse_mode: 'HTML' };
  if (businessConnectionId) body.business_connection_id = businessConnectionId;
  if (messageThreadId) body.message_thread_id = messageThreadId;
  if (replyMarkup) body.reply_markup = replyMarkup;
  await tgPost.call(this, 'sendMessage', body);
}

async function sendPhoto(chatId, photo, caption, replyMarkup) {
  const body = { chat_id: chatId, photo, parse_mode: 'HTML' };
  if (businessConnectionId) body.business_connection_id = businessConnectionId;
  if (messageThreadId) body.message_thread_id = messageThreadId;
  if (caption) body.caption = caption.length > 1000 ? caption.slice(0, 990) + '...' : caption;
  if (replyMarkup) body.reply_markup = replyMarkup;
  try {
    await tgPost.call(this, 'sendPhoto', body);
  } catch (err) {
    try {
      delete body.parse_mode;
      await tgPost.call(this, 'sendPhoto', body);
    } catch (err2) {
      try {
        await sendMessage.call(this, chatId, (caption ? caption + '\n\n' : '') + photo, replyMarkup);
      } catch (err3) {}
    }
  }
}

