function extractTag(str, tagName) {
  const prefix = '[' + tagName;
  const startIdx = str.indexOf(prefix);
  if (startIdx === -1) return null;
  const endIdx = str.indexOf(']', startIdx);
  if (endIdx === -1) return null;
  const rawContent = str.substring(startIdx + prefix.length, endIdx);
  return rawContent.startsWith(':') ? rawContent.substring(1).trim() : rawContent.trim();
}

function removeTag(str, tagName) {
  const prefix = '[' + tagName;
  let startIdx = str.indexOf(prefix);
  while (startIdx !== -1) {
    const endIdx = str.indexOf(']', startIdx);
    if (endIdx !== -1) {
      str = str.substring(0, startIdx) + str.substring(endIdx + 1);
    } else {
      break;
    }
    startIdx = str.indexOf(prefix);
  }
  return str.trim();
}

function extractImageUrl(str) {
  const extensions = ['.jpeg', '.jpg', '.png', '.webp'];
  const lower = str.toLowerCase();
  for (let ext of extensions) {
    let extIdx = lower.indexOf(ext);
    if (extIdx !== -1) {
      let httpIdx = lower.lastIndexOf('http://', extIdx);
      if (httpIdx === -1) httpIdx = lower.lastIndexOf('https://', extIdx);
      if (httpIdx !== -1) {
        return str.substring(httpIdx, extIdx + ext.length);
      }
    }
  }
  return null;
}

