  } catch (e) {}
}

async function sendWaMedia(number, mediaUrl, caption) {
  const plainCaption = caption ? caption.replace(/<[^>]+>/g, '').split('&amp;').join('&') : '';
  try {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: WA_BASE_URL + '/message/sendMedia/' + WA_INSTANCE,
      headers: { apikey: WA_API_KEY, 'Content-Type': 'application/json' },
      body: {
        number: number,
        mediatype: 'image',
        media: mediaUrl,
        caption: plainCaption
      },
